<?php header('Content-Type: application/json');require __DIR__.'/../includes/db.php';$smeId=(int)($_GET['sme_id']??$_GET['seller_id']??0);if(!$smeId){http_response_code(400);echo json_encode(['error'=>'sme_id is required']);exit;}$pdo=get_db();$st=$pdo->prepare('SELECT id,business_name,trust_score,verified_by_admin FROM smes WHERE id=? AND status="active"');$st->execute([$smeId]);$s=$st->fetch();if(!$s){http_response_code(404);echo json_encode(['error'=>'SME not found']);exit;}echo json_encode(['sme_id'=>(int)$s['id'],'seller'=>$s['business_name'],'trust_score'=>(float)$s['trust_score'],'verified'=>(bool)$s['verified_by_admin']]);